/* ---------- Helpers de Perfil Restringido (Javier Andrade) y Bóveda Anti-Reinicio (v43) ---------- */
function isJavierRestrictedUser(user) {
  if (!user) return false;
  if (user.id_usuario === "USR-JAVIER") return true;
  const norm = String(user.nombre || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
  return user.rol === "jefe_taller" && norm.includes("javier andrade");
}

function isUserCatalogAdmin(user) {
  if (!user) return false;
  return (user.rol === "admin" || user.rol === "jefe_taller") && !isJavierRestrictedUser(user);
}

const DEFAULT_DESTAJO_IDS_SET = new Set([
  "DES-DESARME", "DES-LAVQUIM", "DES-APLAN", "DES-GUIAS", "DES-ASIENT",
  "DES-SOLDAD", "DES-ARMADO", "DES-PRUEBA", "DES-CIGUENAL", "DES-BLOQUE"
]);

function isDestajoListLikelyFactoryDefault(list) {
  if (!Array.isArray(list) || list.length === 0) return true;
  if (list.length !== 10) return false;
  const hasCustom = list.some(
    (x) =>
      !x ||
      !DEFAULT_DESTAJO_IDS_SET.has(String(x.id_destajo || "")) ||
      Boolean(x.por_unidad) ||
      String(x.nombre || "") === "Servicio de la camara"
  );
  return !hasCustom;
}

function saveCatalogsSafetyVault(sourceDb) {
  try {
    const d = sourceDb || db;
    if (!d) return;
    const prev = safeJsonParse(localStorage.getItem(CATALOGS_VAULT_KEY), {}) || {};
    const nextVault = { ...prev, updatedAt: Date.now() };
    if (Array.isArray(d.catalogo_servicios) && d.catalogo_servicios.length > 0) {
      const hasPerUnit = d.catalogo_servicios.some((c) => c && c.por_unidad);
      const prevHasPerUnit = Array.isArray(prev.catalogo_servicios) && prev.catalogo_servicios.some((c) => c && c.por_unidad);
      if (hasPerUnit || !prevHasPerUnit || isUserCatalogAdmin(currentUser)) {
        nextVault.catalogo_servicios = d.catalogo_servicios.map((c) => ({ ...c }));
      }
    }
    if (Array.isArray(d.catalogo_destajo) && d.catalogo_destajo.length > 0) {
      if (!isDestajoListLikelyFactoryDefault(d.catalogo_destajo) || !Array.isArray(prev.catalogo_destajo) || isUserCatalogAdmin(currentUser)) {
        nextVault.catalogo_destajo = d.catalogo_destajo.map((w) => ({ ...w }));
      }
    }
    if (d.config && Array.isArray(d.config.bancos_cuentas) && d.config.bancos_cuentas.length > 0) {
      nextVault.bancos_cuentas = d.config.bancos_cuentas.map((b) => ({ ...b }));
    }
    localStorage.setItem(CATALOGS_VAULT_KEY, JSON.stringify(nextVault));
  } catch (e) {}
}

function loadCatalogsSafetyVault() {
  try {
    const parsed = safeJsonParse(localStorage.getItem(CATALOGS_VAULT_KEY), null);
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch (e) {
    return null;
  }
}

/* ---------- Papelera de Recuperación Permanente (v43): Nada se pierde jamás ---------- */
function archiveToRecycleBin(tipoEntidad, idEntidad, etiqueta, datosObj, motivo = "") {
  try {
    if (!db) return null;
    if (!Array.isArray(db.papelera_respaldo)) db.papelera_respaldo = [];
    const cloned = JSON.parse(JSON.stringify(datosObj || {}));
    // Evitar fotos base64 gigantes que saturen una celda de papelera (conservando URLs de Drive y datos completos)
    const stripHugeBase64 = (obj) => {
      if (!obj || typeof obj !== "object") return obj;
      if (Array.isArray(obj)) return obj.map(stripHugeBase64);
      const out = {};
      Object.keys(obj).forEach((k) => {
        const v = obj[k];
        if (typeof v === "string" && v.startsWith("data:image") && v.length > 18000) {
          out[k] = "";
        } else if (v && typeof v === "object") {
          out[k] = stripHugeBase64(v);
        } else {
          out[k] = v;
        }
      });
      return out;
    };
    const nowLocal = getLocalDateTimeISO();
    const entry = {
      id_eliminado: "DEL-" + Date.now() + "-" + Math.random().toString(36).slice(2, 6).toUpperCase(),
      fecha_eliminacion: nowLocal,
      tipo_entidad: String(tipoEntidad || "registro"),
      id_entidad: String(idEntidad || ""),
      etiqueta: String(etiqueta || idEntidad || "Registro eliminado"),
      eliminado_por: currentUser ? currentUser.nombre : "Sistema",
      motivo: String(motivo || "Eliminación directa desde la aplicación"),
      datos: stripHugeBase64(cloned)
    };
    db.papelera_respaldo.unshift(entry);
    if (db.papelera_respaldo.length > 200) {
      db.papelera_respaldo = db.papelera_respaldo.slice(0, 200);
    }
    return entry;
  } catch (e) {
    console.warn("Aviso al archivar en papelera de recuperación:", e);
    return null;
  }
}

function getLocalDateTimeISO() {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  const hh = String(now.getHours()).padStart(2, "0");
  const mm = String(now.getMinutes()).padStart(2, "0");
  const ss = String(now.getSeconds()).padStart(2, "0");
  return `${y}-${m}-${d} ${hh}:${mm}:${ss}`;
}

/* ---------- Helpers de Clasificación de Talleres Externos / Outsourcing (v42) ---------- */
function isExternalUser(user) {
  if (!user) return false;
  return Boolean(
    user.rol === "outsourcing" ||
    user.tipo === "taller_externo" ||
    user.es_externo ||
    String(user.id_usuario || "").startsWith("EXT-")
  );
}

function isSubtaskExternal(sub, usersList) {
  if (!sub) return false;
  if (sub.es_outsourcing || sub.es_repuesto_externo) return true;
  if (sub.tecnico_id) {
    if (String(sub.tecnico_id).startsWith("EXT-")) return true;
    const pool = Array.isArray(usersList) ? usersList : (db && Array.isArray(db.usuarios) ? db.usuarios : []);
    const u = pool.find((x) => x.id_usuario === sub.tecnico_id);
    if (u && isExternalUser(u)) return true;
  }
  return false;
}

function enforceExternalSubtaskDirectState(sub, usersList) {
  if (!sub) return sub;
  if (isSubtaskExternal(sub, usersList)) {
    sub.es_outsourcing = true;
    sub.estado_subtarea = "terminado";
    sub.inicio_activo_ts = null;
    sub.minutos_acumulados = 0;
    sub.tiempo_neto_min = 0;
    if (!sub.fecha_terminado) {
      sub.fecha_terminado = cleanDateISO(sub.fecha_fin || new Date().toISOString(), false);
    }
    if (!sub.fecha_fin) {
      sub.fecha_fin = sub.fecha_terminado;
    }
  }
  return sub;
}

function getPaymentMethodLabel(methodKey) {
  const map = {
    efectivo_usd: "Efectivo Divisas USD",
    efectivo: "Efectivo Divisas USD",
    pago_movil: "Pago Móvil (Bs)",
    efectivo_bs: "Efectivo Bolívares",
    transferencia: "Transferencia Bancaria",
    zelle: "Zelle / Divisas",
    mixto: "Pago Dividido (Partida Doble)"
  };
  return map[methodKey] || String(methodKey || "Efectivo");
}

function suggestMethodForBankAccount(accId) {
  const acc = findBankAccountById(accId);
  if (!acc) return "efectivo_usd";
  const idLow = String(acc.id || "").toLowerCase();
  const nameLow = String(acc.nombre || "").toLowerCase();
  if (idLow.includes("zelle") || nameLow.includes("zelle") || nameLow.includes("binance")) return "zelle";
  if (acc.moneda === "VES" && (idLow.includes("efectivo") || nameLow.includes("efectivo"))) return "efectivo_bs";
  if (acc.moneda === "VES") return "pago_movil";
  if (idLow.includes("efectivo") || nameLow.includes("efectivo") || nameLow.includes("caja")) return "efectivo_usd";
  return "transferencia";
}

/* ---------- Helpers de Separación Real: Servicios Facturados al Cliente (Lista A) vs Trabajos de Destajo (Lista B) ---------- */
function getOrderClientServices(order) {
  if (!order) return [];
  if (Array.isArray(order.servicios_cliente)) {
    return order.servicios_cliente;
  }
  // Retrocompatibilidad para órdenes históricas creadas antes de separar Lista A y Lista B
  const legacySubs = (db.subtareas || []).filter(
    (s) => s.orden_id === order.id_orden && Number(s.monto_servicio) > 0
  );
  return legacySubs.map((s) => ({
    id_item: s.id_subtarea,
    descripcion: s.descripcion_servicio,
    cantidad: 1,
    precio_unitario: Number(s.monto_servicio) || 0,
    monto: Number(s.monto_servicio) || 0,
    es_item_extra: Boolean(s.es_item_extra),
    _legacySubId: s.id_subtarea
  }));
}

function formatServiceDisplayLabel(item) {
  if (!item) return "";
  const qty = Math.max(1, Number(item.cantidad) || 1);
  const unitLabel = item.unidad_label ? ` ${item.unidad_label}` : " uds.";
  const unitPrice = Number(item.precio_unitario) || (qty > 0 ? (Number(item.monto) || 0) / qty : 0);
  if (qty > 1 || item.por_unidad) {
    return `${item.descripcion} (x${qty}${unitLabel} · $${unitPrice.toFixed(2)} c/u)`;
  }
  return String(item.descripcion || "");
}

function formatSubtaskDisplayLabel(sub) {
  if (!sub) return "";
  const qty = Math.max(1, Number(sub.cantidad) || 1);
  const unitLabel = sub.unidad_label ? ` ${sub.unidad_label}` : " uds.";
  if (qty > 1) {
    return `${sub.descripcion_servicio} (x${qty}${unitLabel})`;
  }
  return String(sub.descripcion_servicio || "");
}

function recalcOrderTotalsFromClientServices(order) {
  if (!order) return;
  const servs = getOrderClientServices(order);
  const servTotal = servs.reduce((acc, it) => acc + (Number(it.monto) || 0), 0);
  const repTotal = order.repuestos_comprados_taller
    ? (order.items_repuestos || []).reduce(
        (acc, r) => acc + (Number(r.subtotal) || (Number(r.precio_unitario) || 0) * (Number(r.cantidad) || 1)),
        0
      )
    : 0;
  order.monto_total = servTotal + repTotal;
  order.saldo_pendiente = Math.max(0, order.monto_total - (Number(order.monto_abonado) || 0));
}

function getUserWeeklySalary(u) {
  if (!u) return 0;
  if (u.salario_fijo_semanal === undefined || u.salario_fijo_semanal === null || u.salario_fijo_semanal === "") {
    return 0;
  }
  const n = Number(u.salario_fijo_semanal);
  return Number.isFinite(n) && n >= 0 ? n : 0;
}

function isPartnerInManagementPayroll(u) {
  if (!u || u.es_externo || u.rol === "outsourcing") return false;
  if (u.en_nomina_gerencia === true) return true;
  if (u.en_nomina_gerencia === false) return false;
  return u.id_usuario === "USR-JESUS" || u.id_usuario === "USR-ENRIQUE" || u.id_usuario === "USR-JAVIER";
}

function isPartnerPayrollActive(u) {
  if (!u) return false;
  if (u.nomina_activa !== undefined) return u.nomina_activa !== false && String(u.nomina_activa).toLowerCase() !== "false";
  return u.id_usuario !== "USR-JAVIER";
}

