function addSpareToEditOrder() {
  const sel = document.getElementById("edit-select-spare-inv");
  const qtyEl = document.getElementById("edit-spare-qty");
  if (!sel || !sel.value) return;

  const item = (db.inventario_repuestos || []).find((r) => r.id_repuesto === sel.value);
  if (!item) return;
  const qty = Math.max(1, Number(qtyEl.value) || 1);

  tempEditOrderState.repuestos.push({
    id_repuesto: item.id_repuesto,
    nombre: item.nombre,
    cantidad: qty,
    precio_unitario: Number(item.precio_venta) || 0,
    subtotal: (Number(item.precio_venta) || 0) * qty
  });

  sel.value = "";
  qtyEl.value = "1";
  renderEditSparesTable();
}

function removeSpareFromEditOrder(idx) {
  tempEditOrderState.repuestos.splice(idx, 1);
  renderEditSparesTable();
}

function recalcEditTotals() {
  const servTotal = tempEditOrderState.services.reduce((acc, s) => acc + (Number(s.monto ?? s.monto_servicio) || 0), 0);
  const repTotal = tempEditOrderState.comproRepuestosTaller
    ? tempEditOrderState.repuestos.reduce((acc, r) => acc + (Number(r.subtotal) || (Number(r.precio_unitario) * Number(r.cantidad)) || 0), 0)
    : 0;
  const grandTotal = servTotal + repTotal;

  const order = db.ordenes.find((o) => o.id_orden === tempEditOrderState.orderId);
  const abonado = order ? Number(order.monto_abonado) || 0 : 0;
  const saldo = Math.max(0, grandTotal - abonado);

  const gtEl = document.getElementById("edit-order-grand-total");
  const saldoEl = document.getElementById("edit-order-saldo");
  if (gtEl) gtEl.textContent = "$" + grandTotal.toFixed(2);
  if (saldoEl) {
    saldoEl.textContent = "$" + saldo.toFixed(2);
    saldoEl.style.color = saldo > 0 ? "#f87171" : "#22c55e";
  }
}

function handleEditOrderStageChange(orderId, newStage) {
  const wrap = document.getElementById("edit-ord-reopen-subs-wrap");
  if (!wrap) return;
  const order = (db.ordenes || []).find((o) => o.id_orden === orderId);
  if (!order) return;
  const wasAdvanced = ["calidad", "control_calidad", "entrega", "entregado", "archivado", "terminado"].includes(order.estado_actual);
  const movingToService = newStage === "servicio" || newStage === "asignacion_ejecucion";
  const hasDoneInternalSubs = (db.subtareas || []).some(
    (s) => s.orden_id === orderId && !isSubtaskExternal(s) && s.estado_subtarea === "terminado"
  );
  if (wasAdvanced && movingToService && hasDoneInternalSubs) {
    wrap.classList.remove("hidden");
  } else {
    wrap.classList.add("hidden");
  }
}

function saveEditedCompleteOrder(orderId) {
  const order = db.ordenes.find((o) => o.id_orden === orderId);
  if (!order) return;

  const prevEstado = order.estado_actual;
  const troquel = (document.getElementById("edit-ord-troquel")?.value || "").trim();
  const estado = document.getElementById("edit-ord-estado")?.value || order.estado_actual;
  const condPago = document.getElementById("edit-ord-pago-condicion")?.value || order.tipo_condicion_pago;
  const isPriority = Boolean(document.getElementById("edit-ord-priority")?.checked);
  const reopenWrap = document.getElementById("edit-ord-reopen-subs-wrap");
  const shouldReopenSubs = Boolean(
    reopenWrap &&
    !reopenWrap.classList.contains("hidden") &&
    document.getElementById("edit-ord-reopen-subs")?.checked
  );
  const reopenReason = (document.getElementById("edit-ord-reopen-reason")?.value || "").trim();

  const cliName = (document.getElementById("edit-cli-name")?.value || "").trim();
  const cliDoc = (document.getElementById("edit-cli-doc")?.value || "").trim();
  const cliPhone = (document.getElementById("edit-cli-phone")?.value || "").trim();
  const cliAddr = (document.getElementById("edit-cli-address")?.value || "").trim();
  const cliType = document.getElementById("edit-cli-type")?.value || "particular";

  const pieza = document.getElementById("edit-ord-pieza")?.value || order.datos_motor.tipo_pieza;
  const marca = (document.getElementById("edit-ord-marca")?.value || "").trim();
  const modelo = (document.getElementById("edit-ord-modelo")?.value || "").trim();
  const serial = (document.getElementById("edit-ord-serial")?.value || "").trim();
  const obs = (document.getElementById("edit-ord-obs")?.value || "").trim();

  if (!troquel || !cliName || !cliDoc || !marca || !modelo) {
    showToast("Por favor completa los campos obligatorios (*).", "error");
    return;
  }

  // Actualizar campos de la orden
  const nowTs = Date.now();
  order.codigo_troquel = troquel;
  order.estado_actual = estado;
  order.tipo_condicion_pago = condPago;
  order.prioridad_alta = isPriority;
  order.updated_at = nowTs;
  if (estado !== prevEstado) {
    order.stage_updated_at = nowTs;
  }
  if (estado === "archivado") {
    order.factura_bloqueada = true;
    if (!order.fecha_entrega) order.fecha_entrega = getLocalIsoDate();
    if (!order.fecha_garantia_hasta) {
      const gDate = new Date();
      gDate.setFullYear(gDate.getFullYear() + 1);
      order.fecha_garantia_hasta = getLocalIsoDate(gDate);
    }
  } else if (estado === "entrega" || estado === "entregado") {
    order.factura_bloqueada = false;
  }

  // Si Gerencia devolvió manualmente de Calidad/Entrega a 4. Servicio y marcó reabrir trabajos:
  if (shouldReopenSubs && (estado === "servicio" || estado === "asignacion_ejecucion")) {
    const internalSubs = db.subtareas.filter((s) => s.orden_id === orderId && !isSubtaskExternal(s));
    internalSubs.forEach((s) => {
      s.estado_subtarea = "pendiente";
      s.inicio_activo_ts = null;
      s.qc_reset_ts = nowTs;
      s.updated_at = nowTs;
    });
    order.subestado_ejecucion = "pendiente";
    order.devuelto_calidad = true;
    order.motivo_rechazo_qc = reopenReason || "Devuelto por Gerencia a 4. Servicio para corrección y nueva foto.";
    db.bitacora.push({
      id_mensaje: "MSG-QC-" + nowTs,
      orden_id: order.id_orden,
      codigo_troquel: troquel,
      autor_id: currentUser ? currentUser.id_usuario : "USR-ADMIN",
      autor_nombre: currentUser ? currentUser.nombre : "Gerencia",
      autor_rol: currentUser ? currentUser.rol_label : "Administrador",
      tipo_evento: "rechazo_calidad",
      mensaje: `⚠️ DEVUELTO A 4. SERVICIO por ${currentUser ? currentUser.nombre : "Gerencia"}. ${order.motivo_rechazo_qc} Tareas reabiertas para corregir y subir nueva foto.`,
      foto_adjunta_url: "",
      fecha_hora: getLocalIsoDateTime()
    });
  }

  order.nombre_cliente = cliName;
  order.documento_cliente = cliDoc;
  order.telefono_cliente = cliPhone;
  order.direccion_cliente = cliAddr;
  order.tipo_cliente = cliType;

  order.datos_motor.tipo_pieza = pieza;
  order.datos_motor.marca = marca;
  order.datos_motor.modelo = modelo;
  order.datos_motor.serial = serial;
  order.datos_motor.observaciones = obs;

  order.repuestos_comprados_taller = tempEditOrderState.comproRepuestosTaller;
  order.items_repuestos = tempEditOrderState.repuestos;

  // Guardar Servicios al Cliente (Lista A) SIN tocar ni borrar los trabajos de destajo asignados a técnicos en db.subtareas
  order.servicios_cliente = tempEditOrderState.services.map((s, idx) => {
    const qty = Math.max(1, Number(s.cantidad) || 1);
    const monto = Math.max(0, Number(s.monto ?? s.monto_servicio) || 0);
    const uPrice = Number(s.precio_unitario !== undefined ? s.precio_unitario : monto / qty) || 0;
    return {
      id_item: s.id_item || ("SRV-" + Date.now() + "-" + idx),
      descripcion: s.descripcion || s.descripcion_servicio || "Servicio",
      por_unidad: Boolean(s.por_unidad || qty > 1),
      unidad_label: s.unidad_label || "",
      cantidad: qty,
      precio_unitario: uPrice,
      monto,
      es_item_extra: Boolean(s.es_item_extra)
    };
  });

  // Actualizar troquel en los trabajos de destajo de esta orden (si cambió)
  db.subtareas.forEach((sub) => {
    if (sub.orden_id === orderId) sub.codigo_troquel = troquel;
  });

  // Calcular totales actualizados estrictamente desde Servicios al Cliente + Repuestos
  recalcOrderTotalsFromClientServices(order);

  // Registrar en bitácora (oculto automáticamente para perfiles técnicos por confidencialidad financiera)
  db.bitacora.push({
    id_mensaje: "MSG-" + Date.now(),
    orden_id: order.id_orden,
    codigo_troquel: order.codigo_troquel,
    autor_id: currentUser ? currentUser.id_usuario : "USR-ADMIN",
    autor_nombre: currentUser ? currentUser.nombre : "Sistema",
    autor_rol: currentUser ? currentUser.rol_label : "Administrador",
    tipo_evento: "modificacion",
    mensaje: `Modificación completa guardada para Orden #${troquel}. Total: $${order.monto_total.toFixed(2)}.`,
    foto_adjunta_url: "",
    fecha_hora: getLocalIsoDateTime()
  });

  saveDatabase();
  closeModal();
  renderApp();
  showToast(
    shouldReopenSubs
      ? `Orden #${troquel} actualizada y tareas reabiertas al técnico en 4. Servicio.`
      : `Orden #${troquel} actualizada correctamente.`
  );
}

function saveEditedOrderAndOpenDestajo(orderId) {
  const troquel = (document.getElementById("edit-ord-troquel")?.value || "").trim();
  const cliName = (document.getElementById("edit-cli-name")?.value || "").trim();
  const cliDoc = (document.getElementById("edit-cli-doc")?.value || "").trim();
  const marca = (document.getElementById("edit-ord-marca")?.value || "").trim();
  const modelo = (document.getElementById("edit-ord-modelo")?.value || "").trim();
  if (troquel && cliName && cliDoc && marca && modelo) {
    saveEditedCompleteOrder(orderId);
  } else {
    closeModal();
  }
  openSubtaskAssignmentModal(orderId);
}

function cancelOrArchiveFromEditModal(orderId) {
  const order = db.ordenes.find((o) => o.id_orden === orderId);
  if (!order) return;

  Swal.fire({
    title: `¿Anular o Archivar la Orden #${order.codigo_troquel}?`,
    text: "Selecciona la acción requerida. Al anular, se conserva el correlativo para auditoría sin deuda.",
    icon: "warning",
    showDenyButton: true,
    showCancelButton: true,
    confirmButtonText: "🚫 Anular Orden",
    confirmButtonColor: "#ef4444",
    denyButtonText: "📦 Archivar Orden",
    denyButtonColor: "#0284c7",
    cancelButtonText: "Cancelar"
  }).then((res) => {
    if (res.isConfirmed) {
      Swal.fire({
        title: "Motivo de la Anulación",
        input: "text",
        inputPlaceholder: "Ej: Cliente retiró la pieza sin trabajo / Error de ingreso",
        showCancelButton: true,
        confirmButtonText: "Confirmar Anulación",
        cancelButtonText: "Cancelar"
      }).then((r) => {
        if (r.isConfirmed && r.value) {
          order.estado_actual = "anulado";
          order.motivo_anulacion = r.value;
          order.saldo_pendiente = 0;
          saveDatabase();
          closeModal();
          renderApp();
          showToast(`Orden #${order.codigo_troquel} anulada.`);
        }
      });
    } else if (res.isDenied) {
      archiveOrder(orderId);
      closeModal();
    }
  });
}

/* ============================================================================
   CONTROL DE ASISTENCIA PRESENCIAL POR QR DINÁMICO Y POR PERFIL (JESÚS ANDRADE)
   Entrada, Salida a Almorzar, Regreso y Salida de Jornada con Anti-Fraude
   ============================================================================ */
let kioskTimerInterval = null;
let html5QrCodeScannerInstance = null;

function getTodayAttendanceList() {
  const todayIso = new Date().toISOString().slice(0, 10);
  return (db.asistencias || []).filter((a) => a.fecha === todayIso);
}

function getWorkerCurrentPresence(userId) {
  const todayRecords = getTodayAttendanceList();
  const rec = todayRecords.find((a) => a.usuario_id === userId);
  if (!rec) return { status: "no_ingreso", label: "No ha ingresado hoy", cls: "text-muted", icon: "fa-circle" };
  if (rec.hora_salida) return { status: "salida_final", label: `Jornada Finalizada (${rec.hora_salida})`, cls: "text-secondary", icon: "fa-flag-checkered", rec };
  if (rec.hora_salida_almuerzo && !rec.hora_regreso_almuerzo) return { status: "en_almuerzo", label: `En Almuerzo (${rec.hora_salida_almuerzo})`, cls: "text-warning", icon: "fa-utensils", rec };
  return { status: "en_taller", label: `En Taller (${rec.hora_entrada})`, cls: "text-success", icon: "fa-check-circle", rec };
}

function drawDynamicQrCode(container, text, size = 200) {
  if (!container) return;
  container.innerHTML = "";

  let rendered = false;

  // 1. Intento con David Shim's QRCode constructor local
  if (typeof QRCode === "function") {
    try {
      const qrLevel = (QRCode.CorrectLevel && typeof QRCode.CorrectLevel.L !== "undefined") ? QRCode.CorrectLevel.L : 1;
      new QRCode(container, {
        text: text,
        width: size,
        height: size,
        colorDark: "#0f1638",
        colorLight: "#ffffff",
        correctLevel: qrLevel
      });
      const generated = container.querySelector("canvas, img");
      if (generated) {
        generated.style.display = "block";
        generated.style.margin = "0 auto";
        generated.style.borderRadius = "8px";
        generated.style.background = "#ffffff";
        generated.style.padding = "6px";
        rendered = true;
      }
    } catch (e) {
      console.warn("new QRCode() error:", e);
      container.innerHTML = "";
    }
  }

  // 2. Intento con Ryan Day's QRCode con toCanvas si estuviera cargado
  if (!rendered && typeof QRCode === "object" && typeof QRCode.toCanvas === "function") {
    try {
      const canvas = document.createElement("canvas");
      container.appendChild(canvas);
      QRCode.toCanvas(canvas, text, { width: size, margin: 1, color: { dark: "#0f1638", light: "#ffffff" } }, (err) => {
        if (err) console.error("QRCode.toCanvas error:", err);
      });
      canvas.style.display = "block";
      canvas.style.margin = "0 auto";
      canvas.style.borderRadius = "8px";
      canvas.style.background = "#ffffff";
      canvas.style.padding = "6px";
      rendered = true;
    } catch (e) {
      console.warn("QRCode.toCanvas error:", e);
      container.innerHTML = "";
    }
  }

  // 3. Si no se pudo generar con librerías locales, renderizar con API de imagen QR de alta resolución
  if (!rendered) {
    container.innerHTML = "";
    const img = document.createElement("img");
    img.src = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(text)}&margin=10`;
    img.alt = "QR Asistencia Presencial";
    img.style.width = `${size}px`;
    img.style.height = `${size}px`;
    img.style.display = "block";
    img.style.margin = "0 auto";
    img.style.borderRadius = "8px";
    img.style.background = "#ffffff";
    img.style.padding = "6px";
    img.style.boxShadow = "0 4px 12px rgba(0,0,0,0.25)";

    img.onerror = function() {
      // 4. Fallback Offline solo si falla la imagen y no hay librería disponible
      const displayToken = text.replace(/^RENACER_PRESENCIAL\|/i, "");
      container.innerHTML = `
        <div style="padding:14px; border:2px dashed var(--renacer-gold); border-radius:12px; background:rgba(245,196,0,0.06); text-align:center;">
          <i class="fas fa-qrcode" style="font-size:36px; color:var(--renacer-gold); margin-bottom:6px;"></i>
          <div style="font-size:11px; font-weight:800; color:var(--text-muted); text-transform:uppercase;">TOKEN PRESENCIAL ACTIVO</div>
          <div style="font-family:'JetBrains Mono',monospace; font-size:15px; font-weight:900; color:#38bdf8; word-break:break-all; margin:8px 0; background:rgba(15,22,56,0.6); padding:6px; border-radius:8px;">${displayToken}</div>
          <div style="font-size:10.5px; color:var(--text-muted);">Toca tu nombre a la derecha para certificar asistencia con tu PIN numérico.</div>
        </div>
      `;
    };
    container.appendChild(img);
  }

  // Complemento: Mostrar siempre el token numérico legible abajo
  const displayToken = text.replace(/^RENACER_PRESENCIAL\|/i, "");
  const tokenBadge = document.createElement("div");
  tokenBadge.style.cssText = "margin-top:10px; font-size:11px; color:#cbd5e1; text-align:center; font-family:'JetBrains Mono',monospace;";
  tokenBadge.innerHTML = `<span style="opacity:0.75;">Código token:</span> <strong style="color:var(--renacer-gold); font-size:12px;">${displayToken}</strong>`;
  container.appendChild(tokenBadge);
}

function openAttendanceKioskModal() {
  if (kioskTimerInterval) clearInterval(kioskTimerInterval);

  let secondsLeft = 45;

  // En el kiosco de marcar asistencia SOLO deben figurar los técnicos de taller (Havell, Angel, Jose)
  const activeWorkers = (db.usuarios || []).filter(
    (u) => u.activo && u.rol === "tecnico"
  );

  const workersProfilesHtml = activeWorkers
    .map((w) => {
      const pres = getWorkerCurrentPresence(w.id_usuario);
      let badgeColor = "#94a3b8";
      let badgeText = "Sin marcar";
      let dotIcon = "fa-circle";
      if (pres.status === "en_taller") {
        badgeColor = "#22c55e";
        badgeText = "En Taller";
        dotIcon = "fa-check-circle";
      } else if (pres.status === "en_almuerzo") {
        badgeColor = "#f59e0b";
        badgeText = "Almuerzo";
        dotIcon = "fa-utensils";
      } else if (pres.status === "salida_final") {
        badgeColor = "#64748b";
        badgeText = "Salió";
        dotIcon = "fa-flag-checkered";
      }

      return `
        <button type="button" class="kiosk-worker-card-btn" onclick="quickAttendanceByProfile('${w.id_usuario}')" title="Marcar entrada/salida para ${w.nombre}">
          <div style="display:flex; justify-content:space-between; align-items:center;">
            <strong style="font-size:12.5px; color:var(--text-main);">${w.nombre}</strong>
            <span style="font-size:10.5px; font-weight:800; color:${badgeColor}; display:flex; align-items:center; gap:4px;">
              <i class="fas ${dotIcon}"></i> ${badgeText}
            </span>
          </div>
          <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">
            ${w.rol_label || w.rol} · <span style="color:var(--renacer-gold); font-weight:700;">Tocar para marcar</span>
          </div>
        </button>
      `;
    })
    .join("");

  openModal({
    title: "Kiosco de Asistencia Presencial (QR Dinámico y Perfil)",
    icon: "fa-qrcode",
    wide: true,
    body: `
      <div style="display:grid; grid-template-columns: 1fr 1fr; gap:18px; align-items:start;" class="kiosk-grid-responsive">
        <!-- COLUMNA IZQUIERDA: QR DINÁMICO ANTI-FRAUDE 45s -->
        <div class="attendance-kiosk-wrapper" style="background:var(--bg-card); border:1.5px solid var(--border-subtle); border-radius:16px; padding:18px;">
          <div style="font-size:12.5px; color:var(--renacer-gold); font-weight:900; text-transform:uppercase; margin-bottom:4px;">
            <i class="fas fa-camera"></i> Escanear con Teléfono
          </div>
          <p style="font-size:11.5px; color:var(--text-muted); margin-bottom:8px; line-height:1.4;">
            El código cambia cada <strong>45 segundos</strong> para certificar presencia física en el taller (evita reenvíos por WhatsApp).
          </p>

          <div class="attendance-qr-card" style="margin:8px 0;">
            <div id="kiosk-qr-canvas"></div>
          </div>

          <div id="kiosk-timer-display" class="qr-countdown-badge">
            <i class="fas fa-stopwatch"></i> Actualizando en: <strong id="kiosk-secs-num">45</strong>s
          </div>

          <button type="button" class="btn btn--ghost btn--xs" onclick="generateNewKioskQr()" style="margin-top:10px; font-size:11px;">
            <i class="fas fa-sync-alt"></i> Forzar nuevo código
          </button>
        </div>

        <!-- COLUMNA DERECHA: REGISTRO DIRECTO POR PERFIL (SI NO TIENEN TELÉFONO) -->
        <div style="background:var(--bg-card); border:1.5px solid var(--border-subtle); border-radius:16px; padding:18px;">
          <div style="font-size:12.5px; color:#38bdf8; font-weight:900; text-transform:uppercase; margin-bottom:4px;">
            <i class="fas fa-user-circle"></i> Marcar por Perfil (Sin Teléfono)
          </div>
          <p style="font-size:11.5px; color:var(--text-muted); margin-bottom:12px;">
            Si se dañó el teléfono o no lo tienen a mano, el técnico toca su perfil e ingresa su PIN numérico.
          </p>

          <div style="display:grid; gap:8px;">
            ${workersProfilesHtml}
          </div>

          <div style="margin-top:14px; padding:10px; background:rgba(245,196,0,0.06); border:1px dashed var(--renacer-gold); border-radius:10px; font-size:11px; color:var(--text-main);">
            <i class="fas fa-info-circle" style="color:var(--renacer-gold);"></i> 
            <span id="kiosk-notice-display">${escapeHtml(getCustomText("attendance_notice", DEFAULT_TEXT_CUSTOMIZATIONS.attendance_notice))}</span>
          </div>
        </div>
      </div>
    `
  });

  window.generateNewKioskQr = function() {
    const canvasBox = document.getElementById("kiosk-qr-canvas");
    if (!canvasBox) return;
    secondsLeft = 45;

    const token = `RENACER_PRESENCIAL|${Date.now()}|${Math.floor(100000 + Math.random() * 900000)}`;
    drawDynamicQrCode(canvasBox, token, 200);
  };

  generateNewKioskQr();

  kioskTimerInterval = setInterval(() => {
    secondsLeft--;
    const numEl = document.getElementById("kiosk-secs-num");
    const badgeEl = document.getElementById("kiosk-timer-display");
    if (numEl) numEl.textContent = secondsLeft;
    if (badgeEl) {
      if (secondsLeft <= 10) badgeEl.classList.add("warning");
      else badgeEl.classList.remove("warning");
    }
    if (secondsLeft <= 0) {
      generateNewKioskQr();
    }
  }, 1000);
}

function quickAttendanceByProfile(userId) {
  const user = (db.usuarios || []).find((u) => u.id_usuario === userId);
  if (!user) return;

  Swal.fire({
    title: `Marcar Asistencia: ${user.nombre}`,
    text: "Ingresa tu PIN numérico personal para validar:",
    input: "password",
    inputAttributes: {
      inputmode: "numeric",
      maxlength: 6,
      autocapitalize: "off",
      autocorrect: "off"
    },
    showCancelButton: true,
    confirmButtonText: "Continuar",
    confirmButtonColor: "#f5c400",
    cancelButtonText: "Cancelar",
    preConfirm: (pin) => {
      if (!pin) {
        Swal.showValidationMessage("Debes ingresar tu PIN.");
        return false;
      }
      if (String(user.pin || "000000").trim() !== pin.trim()) {
        Swal.showValidationMessage("PIN incorrecto.");
        return false;
      }
      return true;
    }
  }).then((res) => {
    if (res.isConfirmed) {
      handleAttendanceActionForUser(user, "perfil_kiosco");
    }
  });
}

function resolveHtml5QrcodeCtor() {
  if (typeof window !== "undefined") {
    if (typeof window.Html5Qrcode === "function") return window.Html5Qrcode;
    if (window.__Html5QrcodeLibrary__ && typeof window.__Html5QrcodeLibrary__.Html5Qrcode === "function") {
      window.Html5Qrcode = window.__Html5QrcodeLibrary__.Html5Qrcode;
      return window.Html5Qrcode;
    }
  }
  if (typeof Html5Qrcode === "function") return Html5Qrcode;
  return null;
}

function loadExternalScriptOnce(src, timeoutMs = 8000) {
  return new Promise((resolve) => {
    if (typeof document === "undefined") return resolve(false);
    let settled = false;
    const finish = (ok) => {
      if (settled) return;
      settled = true;
      resolve(ok);
    };
    const script = document.createElement("script");
    script.src = src;
    script.async = true;
    const timer = setTimeout(() => finish(false), timeoutMs);
    script.onload = () => {
      clearTimeout(timer);
      finish(true);
    };
    script.onerror = () => {
      clearTimeout(timer);
      finish(false);
    };
    document.head.appendChild(script);
  });
}

async function ensureHtml5QrcodeLoaded() {
  let ctor = resolveHtml5QrcodeCtor();
  if (ctor) return ctor;
  const sources = [
    `./html5-qrcode.min.js?v=20261124_v45`,
    "https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js",
    "https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"
  ];
  for (let i = 0; i < sources.length; i++) {
    await loadExternalScriptOnce(sources[i], 7000);
    ctor = resolveHtml5QrcodeCtor();
    if (ctor) return ctor;
  }
  return null;
}

function stopActiveQrScannerSafely() {
  if (!html5QrCodeScannerInstance) return;
  const inst = html5QrCodeScannerInstance;
  html5QrCodeScannerInstance = null;
  try {
    Promise.resolve(inst.stop())
      .then(() => {
        try { inst.clear(); } catch (e) {}
      })
      .catch(() => {
        try { inst.clear(); } catch (e) {}
      });
  } catch (e) {}
}

function openTechnicianQrScanModal() {
  stopActiveQrScannerSafely();

  openModal({
    title: "Escanear QR de Asistencia Presencial",
    icon: "fa-camera",
    wide: false,
    body: `
      <div style="text-align:center; padding:12px;">
        <p style="font-size:12.5px; color:var(--text-muted); margin-bottom:12px;">
          Apunta la cámara de tu teléfono a la pantalla de recepción para certificar tu presencia física en el taller.
        </p>

        <div id="tech-qr-reader" class="attendance-scanner-box"></div>

        <div id="tech-scan-status" style="font-size:12px; font-weight:800; color:var(--text-main); margin-top:12px;">
          <i class="fas fa-spinner fa-spin"></i> Iniciando lector QR y cámara...
        </div>

        <div style="margin-top:14px; display:flex; justify-content:center; gap:8px; flex-wrap:wrap;">
          <button type="button" class="btn btn--ghost btn--sm" onclick="stopActiveQrScannerSafely(); promptManualPinAttendance();">
            ¿Problemas con la cámara? Registrar con PIN
          </button>
        </div>
      </div>
    `
  });

  setTimeout(async () => {
    const statusEl = document.getElementById("tech-scan-status");
    const readerEl = document.getElementById("tech-qr-reader");
    if (!readerEl) return;

    if (typeof window !== "undefined" && window.isSecureContext === false) {
      if (statusEl) {
        statusEl.innerHTML = `<span style="color:#f59e0b;"><i class="fas fa-lock"></i> La cámara requiere conexión segura (HTTPS). Abre la app desde el enlace oficial o usa tu PIN.</span>`;
      }
      return;
    }

    const QrCtor = await ensureHtml5QrcodeLoaded();
    if (!QrCtor) {
      if (statusEl) {
        statusEl.innerHTML = `<span style="color:#ef4444;"><i class="fas fa-wifi"></i> No se pudo cargar el lector QR (verifica tu conexión a internet). Usa la opción de PIN abajo.</span>`;
      }
      return;
    }

    if (!document.getElementById("tech-qr-reader")) return;

    const onScanSuccess = (decodedText) => handleScannedAttendanceToken(decodedText);
    const scanCfg = { fps: 10, qrbox: { width: 220, height: 220 } };

    try {
      html5QrCodeScannerInstance = new QrCtor("tech-qr-reader");
      await html5QrCodeScannerInstance.start({ facingMode: "environment" }, scanCfg, onScanSuccess, () => {});
      if (statusEl) {
        statusEl.innerHTML = `<span style="color:#22c55e;"><i class="fas fa-check-circle"></i> Cámara lista. Apunta al código QR en pantalla...</span>`;
      }
    } catch (firstErr) {
      // Segundo intento: seleccionar explícitamente cámara trasera o primera disponible
      try {
        const cams = typeof QrCtor.getCameras === "function" ? await QrCtor.getCameras() : [];
        if (cams && cams.length > 0 && document.getElementById("tech-qr-reader")) {
          const backCam = cams.find((c) => /back|rear|traser|environment/i.test(String(c.label || ""))) || cams[cams.length - 1];
          await html5QrCodeScannerInstance.start(backCam.id, scanCfg, onScanSuccess, () => {});
          if (statusEl) {
            statusEl.innerHTML = `<span style="color:#22c55e;"><i class="fas fa-check-circle"></i> Cámara lista. Apunta al código QR en pantalla...</span>`;
          }
          return;
        }
        throw firstErr;
      } catch (err) {
        stopActiveQrScannerSafely();
        const errMsg = String(err && err.message ? err.message : err || "");
        const friendly = /NotAllowedError|Permission/i.test(errMsg)
          ? "Permiso de cámara denegado. Permite el acceso a la cámara en tu navegador o usa el registro con PIN."
          : /NotFoundError|Requested device not found/i.test(errMsg)
          ? "No se detectó cámara disponible en este dispositivo. Usa el registro con PIN."
          : `No se pudo activar la cámara (${escapeHtml(errMsg || "error de dispositivo")}). Usa la opción de PIN.`;
        if (statusEl) {
          statusEl.innerHTML = `<span style="color:#ef4444;"><i class="fas fa-exclamation-triangle"></i> ${friendly}</span>`;
        }
      }
    }
  }, 300);
}

function handleScannedAttendanceToken(token) {
  if (!token || !token.startsWith("RENACER_PRESENCIAL|")) {
    showToast("Código QR no válido para asistencia de Renacer.", "error");
    return;
  }

  const parts = token.split("|");
  const timestamp = Number(parts[1]) || 0;
  const ageMs = Date.now() - timestamp;

  // Verificación anti-fraude: código emitido hace menos de 90 segundos
  if (ageMs > 90000) {
    Swal.fire({
      icon: "error",
      title: "Código QR Expirado",
      text: "El código escaneado ha vencido o fue tomado de una fotografía vieja. Debes escanear el código que se está mostrando en vivo en la pantalla del taller."
    });
    return;
  }

  stopActiveQrScannerSafely();
  closeModal();

  const user = currentUser || db.usuarios.find((u) => u.rol === "tecnico") || db.usuarios[0];
  handleAttendanceActionForUser(user, "qr_dinamico_presencial");
}

function promptManualPinAttendance() {
  stopActiveQrScannerSafely();
  const isLockedToSelf = Boolean(currentUser && currentUser.rol !== "admin" && currentUser.rol !== "jefe_taller");
  const users = isLockedToSelf
    ? [currentUser]
    : (db.usuarios || []).filter((u) => u.activo && (u.rol === "tecnico" || u.rol === "inventario" || u.rol === "recepcion" || u.rol === "admin" || u.rol === "jefe_taller"));
  const defaultSelId = currentUser ? currentUser.id_usuario : (users[0] ? users[0].id_usuario : "");
  const optionsHtml = users
    .map((u) => `<option value="${u.id_usuario}" ${u.id_usuario === defaultSelId ? "selected" : ""}>${escapeHtml(u.nombre)} (${escapeHtml(u.rol_label || u.rol)})</option>`)
    .join("");

  const userFieldHtml = isLockedToSelf
    ? `
        <div>
          <label style="font-weight:700;">Trabajador Activo:</label>
          <div style="margin:6px 0 8px 0; padding:10px 12px; border-radius:8px; background:rgba(245,223,0,0.12); border:1px solid rgba(245,223,0,0.4); font-weight:800; color:var(--renacer-gold, #f5c400);">
            <i class="fas fa-user-check"></i> ${escapeHtml(currentUser.nombre)} (${escapeHtml(currentUser.rol_label || currentUser.rol)})
          </div>
          <input type="hidden" id="swal-pin-user" value="${escapeHtml(currentUser.id_usuario)}" />
        </div>
      `
    : `
        <div>
          <label style="font-weight:700;">Selecciona tu Nombre:</label>
          <select id="swal-pin-user" class="swal2-input" style="width:100%; margin:4px 0 10px 0; font-size:13px;">
            ${optionsHtml}
          </select>
        </div>
      `;

  Swal.fire({
    title: "Registro de Asistencia con PIN",
    html: `
      <div style="text-align:left; font-size:13px; display:grid; gap:10px;">
        ${userFieldHtml}
        <div>
          <label style="font-weight:700;">PIN Numérico:</label>
          <input type="password" id="swal-pin-code" class="swal2-input" inputmode="numeric" placeholder="Ingresa tu PIN" style="width:100%; margin:4px 0 0 0;" />
        </div>
      </div>
    `,
    showCancelButton: true,
    confirmButtonText: "Continuar",
    confirmButtonColor: "#f5c400",
    cancelButtonText: "Cancelar",
    preConfirm: () => {
      const uId = document.getElementById("swal-pin-user")?.value;
      const pin = document.getElementById("swal-pin-code")?.value;
      if (!uId || !pin) {
        Swal.showValidationMessage("Selecciona tu usuario e ingresa el PIN.");
        return false;
      }
      const user = db.usuarios.find((x) => x.id_usuario === uId);
      if (!user || String(user.pin || "000000").trim() !== pin.trim()) {
        Swal.showValidationMessage("PIN incorrecto.");
        return false;
      }
      return user;
    }
  }).then((res) => {
    if (res.isConfirmed && res.value) {
      handleAttendanceActionForUser(res.value, "pin_manual_kiosco");
    }
  });
}

function handleAttendanceActionForUser(user, method) {
  const now = new Date();
  const todayIso = now.toISOString().slice(0, 10);
  const timeStr = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

  let existing = (db.asistencias || []).find((a) => a.fecha === todayIso && a.usuario_id === user.id_usuario);

  const entradaText = existing?.hora_entrada ? `✅ Entrada: ${existing.hora_entrada} (${existing.estado})` : "⏳ Sin marcar entrada";
  const almuerzoSalText = existing?.hora_salida_almuerzo ? `✅ Salió a almuerzo: ${existing.hora_salida_almuerzo}` : "⏳ Sin salida a almuerzo";
  const almuerzoRegText = existing?.hora_regreso_almuerzo ? `✅ Regresó de almuerzo: ${existing.hora_regreso_almuerzo}` : "⏳ Sin regreso de almuerzo";
  const salidaText = existing?.hora_salida ? `✅ Salida final: ${existing.hora_salida}` : "⏳ Sin salida de jornada";

  Swal.fire({
    title: `Control de Horario: ${user.nombre}`,
    html: `
      <div style="text-align:left; font-size:13px;">
        <div style="background:var(--bg-input); padding:10px 14px; border-radius:12px; margin-bottom:14px; border:1px solid var(--border-subtle); line-height:1.6;">
          <div style="font-weight:800; color:var(--renacer-gold); margin-bottom:4px;">
            <i class="fas fa-calendar-day"></i> Registro de Hoy (${formatDateHuman(todayIso, false)}) · Hora Actual: <strong>${timeStr}</strong>
          </div>
          <div style="font-size:12px; color:var(--text-muted);">${entradaText}</div>
          <div style="font-size:12px; color:var(--text-muted);">${almuerzoSalText} · ${almuerzoRegText}</div>
          <div style="font-size:12px; color:var(--text-muted);">${salidaText}</div>
        </div>

        <p style="font-weight:800; margin-bottom:10px; color:var(--text-main);">Selecciona la acción a certificar en este momento:</p>

        <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px;">
          <button type="button" id="swal-att-btn-entrada" class="btn btn--gold" style="padding:10px; font-weight:800; font-size:12px; display:flex; align-items:center; justify-content:center; gap:6px;">
            <i class="fas fa-sun"></i> 1. Entrada
          </button>
          <button type="button" id="swal-att-btn-almuerzo-sal" class="btn btn--warning" style="padding:10px; font-weight:800; font-size:12px; display:flex; align-items:center; justify-content:center; gap:6px;">
            <i class="fas fa-utensils"></i> 2. Salida Almuerzo
          </button>
          <button type="button" id="swal-att-btn-almuerzo-reg" class="btn btn--primary" style="padding:10px; font-weight:800; font-size:12px; display:flex; align-items:center; justify-content:center; gap:6px;">
            <i class="fas fa-undo"></i> 3. Regreso Almuerzo
          </button>
          <button type="button" id="swal-att-btn-salida" class="btn btn--ghost" style="padding:10px; font-weight:800; font-size:12px; border-color:#0284c7; color:#38bdf8; display:flex; align-items:center; justify-content:center; gap:6px;">
            <i class="fas fa-door-open"></i> 4. Salida Jornada
          </button>
        </div>
      </div>
    `,
    showConfirmButton: false,
    showCancelButton: true,
    cancelButtonText: "Cerrar",
    didOpen: () => {
      document.getElementById("swal-att-btn-entrada")?.addEventListener("click", () => {
        executeAttendanceAction(user, "entrada", method);
      });
      document.getElementById("swal-att-btn-almuerzo-sal")?.addEventListener("click", () => {
        executeAttendanceAction(user, "salida_almuerzo", method);
      });
      document.getElementById("swal-att-btn-almuerzo-reg")?.addEventListener("click", () => {
        executeAttendanceAction(user, "regreso_almuerzo", method);
      });
      document.getElementById("swal-att-btn-salida")?.addEventListener("click", () => {
        executeAttendanceAction(user, "salida_jornada", method);
      });
    }
  });
}

function executeAttendanceAction(user, action, method) {
  const now = new Date();
  const todayIso = now.toISOString().slice(0, 10);
  const timeStr = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

  let existing = (db.asistencias || []).find((a) => a.fecha === todayIso && a.usuario_id === user.id_usuario);

  if (action === "entrada") {
    const isLate = now.getHours() > 9 || (now.getHours() === 9 && now.getMinutes() > 15);
    if (!existing) {
      existing = {
        id_asist: "ASI-" + Date.now(),
        fecha: todayIso,
        usuario_id: user.id_usuario,
        nombre: user.nombre,
        hora_registro: timeStr,
        hora_entrada: timeStr,
        hora_salida_almuerzo: "",
        hora_regreso_almuerzo: "",
        hora_salida: "",
        estado_hoy: "En Taller",
        estado: isLate ? "Tardanza" : "Puntual",
        metodo: method,
        observacion: isLate
          ? "Llegada después de las 9:15 AM (Tardanza registrada - Horario oficial 9:00 AM – 6:00 PM)"
          : "Asistencia presencial verificada puntual (Horario 9:00 AM – 6:00 PM)",
        dispositivo: navigator.userAgent.slice(0, 50)
      };
      if (!Array.isArray(db.asistencias)) db.asistencias = [];
      db.asistencias.unshift(existing);
    } else {
      existing.hora_entrada = timeStr;
      existing.estado = isLate ? "Tardanza" : "Puntual";
      existing.estado_hoy = "En Taller";
    }
    saveDatabase();
    Swal.close();
    closeModal();
    renderApp();
    showToast(`Entrada registrada para ${user.nombre} (${timeStr} - ${isLate ? "Tardanza" : "Puntual"}).`, isLate ? "warning" : "info");
    return;
  }

  if (!existing) {
    existing = {
      id_asist: "ASI-" + Date.now(),
      fecha: todayIso,
      usuario_id: user.id_usuario,
      nombre: user.nombre,
      hora_registro: timeStr,
      hora_entrada: "09:00 AM",
      hora_salida_almuerzo: "",
      hora_regreso_almuerzo: "",
      hora_salida: "",
      estado_hoy: "En Taller",
      estado: "Puntual",
      metodo: method,
      observacion: "Asistencia presencial en taller",
      dispositivo: navigator.userAgent.slice(0, 50)
    };
    if (!Array.isArray(db.asistencias)) db.asistencias = [];
    db.asistencias.unshift(existing);
  }

  if (action === "salida_almuerzo") {
    existing.hora_salida_almuerzo = timeStr;
    existing.estado_hoy = "En Almuerzo";
    showToast(`Salida a almorzar registrada para ${user.nombre} (${timeStr}).`);
  } else if (action === "regreso_almuerzo") {
    existing.hora_regreso_almuerzo = timeStr;
    existing.estado_hoy = "En Taller";
    showToast(`Regreso de almuerzo registrado para ${user.nombre} (${timeStr}).`);
  } else if (action === "salida_jornada") {
    existing.hora_salida = timeStr;
    existing.estado_hoy = "Jornada Finalizada";
    showToast(`Salida final de jornada registrada para ${user.nombre} (${timeStr}).`);
  }

  saveDatabase();
  Swal.close();
  closeModal();
  renderApp();
}

function markLunchReturnPrompt(asistId) {
  const rec = (db.asistencias || []).find((a) => a.id_asist === asistId);
  if (!rec) return;
  const now = new Date();
  const timeStr = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  rec.hora_regreso_almuerzo = timeStr;
  rec.estado_hoy = "En Taller";
  saveDatabase();
  Swal.close();
  closeModal();
  showToast(`Regreso de almuerzo registrado para ${rec.nombre} (${timeStr}).`);
  renderApp();
}



/* ============================================================================
   PLANILLA / HOJA DE SERVICIO Y PRESUPUESTO PDF (ACTUALIZABLE A FACTURA FÍSICA)
   + ARCHIVO AUTOMÁTICO EN GOOGLE DRIVE Y EXPORTACIÓN POR RANGO DE FECHAS
   ============================================================================ */
function buildOrderPrintableBodySection(order) {
  const clientServices = getOrderClientServices(order);
  const repuestos = Array.isArray(order.items_repuestos) ? order.items_repuestos : [];
  const docCfg = (db.config && db.config.doc_template) || {};
  const docTitle = docCfg.modo_factura_activa ? "FACTURA DE SERVICIO" : (docCfg.tipo_documento || "ORDEN Y PRESUPUESTO");
  const companyName = docCfg.razon_social || "RECTIFICADORA RENACER C.A.";
  const companySub = docCfg.subtitulo || "Especialistas en Rectificación de Motores, Cámaras, Cigüeñales y Bloques · Maracaibo, Zulia";
  const companyRif = docCfg.rif ? ` · RIF: ${escapeHtml(docCfg.rif)}` : "";
  const isWaitingApproval =
    order.estado_actual === "diagnostico_presupuesto" ||
    order.estado_actual === "esperando_aprobacion_abono" ||
    order.estado_actual === "aprobacion";

  let itemsHtml = "";
  let counter = 1;

  clientServices.forEach((s) => {
    const qty = Math.max(1, Number(s.cantidad) || 1);
    const totalVal = Number(s.monto) || 0;
    const unitVal = Number(s.precio_unitario !== undefined ? s.precio_unitario : totalVal / qty) || 0;
    const unitDesc = s.unidad_label && qty > 1 ? ` ${escapeHtml(s.unidad_label)}` : "";
    itemsHtml += `
      <tr>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:center;">${counter++}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px;"><strong>${escapeHtml(s.descripcion)}</strong>${qty > 1 ? ` <span style="font-size:11px; color:#475569;">(${qty}${unitDesc})</span>` : ""}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:center;">Servicio Técnico</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px;">Taller Renacer</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:center;">${qty}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:right;">$${unitVal.toFixed(2)}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:right; font-weight:800;">$${totalVal.toFixed(2)}</td>
      </tr>
    `;
  });

  repuestos.forEach((r) => {
    const sub = (Number(r.precio_unitario) || 0) * (Number(r.cantidad) || 1);
    itemsHtml += `
      <tr>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:center;">${counter++}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px;"><strong>${escapeHtml(r.nombre)}</strong> (Repuesto)</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:center;">Repuesto Taller</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px;">Inventario / Gerencia</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:center;">${r.cantidad}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:right;">$${Number(r.precio_unitario).toFixed(2)}</td>
        <td style="border:1px solid #cbd5e1; padding:6px 10px; text-align:right; font-weight:800;">$${sub.toFixed(2)}</td>
      </tr>
    `;
  });

  return `
    <div class="order-pdf-sheet">
      <div class="header-box">
        <div>
          <div class="title-company">${escapeHtml(companyName)}</div>
          <div class="biblical-quote">"Aunque tu principio haya sido pequeño, tu postrer estado será muy grande." (Job 8:7)</div>
          <div style="font-size:11px; color:#64748b; margin-top:3px;">
            ${escapeHtml(companySub)}${companyRif}
          </div>
        </div>
        <div class="order-badge-box">
          <div style="font-size:11px; color:#64748b; font-weight:bold;">${escapeHtml(docTitle)}</div>
          <div style="font-size:22px; font-weight:900; color:#0f1638; font-family:monospace;">ORDEN #${escapeHtml(order.codigo_troquel)}</div>
          <div style="font-size:11px; color:#0284c7; font-weight:bold;">Fecha: ${formatDateHuman(order.fecha_ingreso, false)}</div>
        </div>
      </div>

      ${
        isWaitingApproval
          ? `<div class="approval-banner">
               <span>⏳ ESTADO DEL PRESUPUESTO: ESPERANDO APROBACIÓN DEL CLIENTE</span>
               <span>Plazo de vigencia / retiro: 3 días</span>
             </div>`
          : ""
      }

      <div class="grid-info">
        <div class="info-card">
          <h4>Datos del Cliente / Taller</h4>
          <div><strong>Cliente:</strong> ${escapeHtml(order.nombre_cliente)}</div>
          <div><strong>Cédula / RIF:</strong> ${escapeHtml(order.documento_cliente)}</div>
          <div><strong>Teléfono:</strong> ${escapeHtml(order.telefono_cliente)}</div>
          <div><strong>Dirección:</strong> ${escapeHtml(order.direccion_cliente || "No especificada")}</div>
          <div><strong>Tipo de Cliente:</strong> ${escapeHtml(order.tipo_cliente || "Particular")}</div>
        </div>
        <div class="info-card">
          <h4>Datos Técnicos de la Pieza / Motor</h4>
          <div><strong>Pieza:</strong> ${escapeHtml(order.datos_motor?.tipo_pieza || "Cámara")}</div>
          <div><strong>Vehículo / Marca:</strong> ${escapeHtml(order.datos_motor?.marca || "")} ${escapeHtml(order.datos_motor?.modelo || "")}</div>
          <div><strong>Serial Fundición:</strong> ${escapeHtml(order.datos_motor?.serial || "S/N")}</div>
          <div><strong>Diagnóstico Inicial:</strong> ${escapeHtml(order.datos_motor?.observaciones || "Ingreso regular a taller")}</div>
        </div>
      </div>

      <table>
        <thead>
          <tr>
            <th>#</th>
            <th style="text-align:left;">Descripción del Trabajo / Repuesto</th>
            <th>Categoría</th>
            <th style="text-align:left;">Responsable</th>
            <th>Cant.</th>
            <th style="text-align:right;">P. Unit ($)</th>
            <th style="text-align:right;">Total ($)</th>
          </tr>
        </thead>
        <tbody>
          ${itemsHtml}
        </tbody>
      </table>

      <table class="totals-table">
        <tr>
          <td style="padding:4px 8px; font-weight:bold;">${docCfg.modo_factura_activa ? "Total Factura:" : "Total Presupuesto:"}</td>
          <td style="padding:4px 8px; text-align:right; font-weight:900; font-size:16px;">$${Number(order.monto_total).toFixed(2)}</td>
        </tr>
        <tr>
          <td style="padding:4px 8px; color:#16a34a; font-weight:bold;">Monto Abonado:</td>
          <td style="padding:4px 8px; text-align:right; color:#16a34a; font-weight:900;">$${Number(order.monto_abonado).toFixed(2)}</td>
        </tr>
        <tr style="border-top:2px solid #0f1638;">
          <td style="padding:6px 8px; font-weight:bold; color:${order.saldo_pendiente > 0 ? '#dc2626' : '#16a34a'};">Saldo Pendiente:</td>
          <td style="padding:6px 8px; text-align:right; font-weight:900; font-size:16px; color:${order.saldo_pendiente > 0 ? '#dc2626' : '#16a34a'};">$${Number(order.saldo_pendiente).toFixed(2)}</td>
        </tr>
      </table>

      <div class="policies-box">
        <strong style="text-transform:uppercase; color:#b45309;">Políticas Oficiales y Términos de Garantía Renacer:</strong>
        <ol style="margin:4px 0 0 18px; padding:0;">
          <li><strong>Garantía Oficial de 1 Año:</strong> Garantía de 365 días sobre tolerancias de rectificación y cepillado (no cubre recalentamiento severo posterior por falta de refrigerante).</li>
          <li><strong>Plazo de Aprobación:</strong> El cliente dispone de un plazo mínimo de 3 días para aprobar presupuesto o retirar piezas.</li>
          <li><strong>Custodia y Retiro:</strong> La rectificadora no asume responsabilidad por piezas tras 30 días sin concretar trabajo. Retiro exclusivo previa liquidación del 100%.</li>
          <li><strong>Ajustes por Limpieza:</strong> Daños o fisuras internas descubiertas durante el baño químico serán notificadas de inmediato.</li>
        </ol>
      </div>

      <div class="signatures-grid">
        <div class="sig-line">Firma Técnico / Gerencia</div>
        <div class="sig-line">Firma Control de Calidad</div>
        <div class="sig-line">Firma y Cédula del Cliente</div>
      </div>
    </div>
  `;
}

const ORDER_PDF_SHARED_CSS = `
  body { font-family: 'Segoe UI', Arial, sans-serif; color: #0f172a; margin: 20px; line-height: 1.4; font-size: 13px; }
  .header-box { border-bottom: 2px solid #0f1638; padding-bottom: 12px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: center; }
  .title-company { font-size: 22px; font-weight: 900; color: #0f1638; letter-spacing: 0.5px; }
  .biblical-quote { font-style: italic; font-size: 11px; color: #b45309; font-weight: bold; }
  .order-badge-box { text-align: right; background: #f8fafc; border: 2px solid #cbd5e1; border-radius: 8px; padding: 8px 14px; }
  .approval-banner { background: #fef9c3; border: 1.5px solid #ca8a04; color: #854d0e; border-radius: 8px; padding: 8px 14px; margin-bottom: 14px; font-size: 12px; font-weight: 700; display: flex; justify-content: space-between; align-items: center; }
  .grid-info { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
  .info-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 10px 14px; }
  .info-card h4 { margin: 0 0 6px 0; font-size: 12px; color: #0f1638; text-transform: uppercase; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
  th { background: #0f1638; color: #ffffff; padding: 8px 10px; font-size: 11px; text-transform: uppercase; }
  .totals-table { width: 320px; margin-left: auto; margin-bottom: 16px; }
  .policies-box { background: #fffbeb; border: 1px dashed #d97706; border-radius: 8px; padding: 10px 14px; font-size: 11px; margin-bottom: 24px; }
  .signatures-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; margin-top: 40px; text-align: center; }
  .sig-line { border-top: 1px solid #475569; padding-top: 6px; font-size: 11.5px; font-weight: bold; }
  .action-bar { margin-top: 24px; padding: 14px; background: #f1f5f9; border: 1px solid #cbd5e1; border-radius: 10px; display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
  .action-btn { padding: 10px 16px; font-size: 13px; font-weight: bold; border: none; border-radius: 8px; cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; gap: 6px; }
  .page-break { page-break-after: always; break-after: page; }
  @media print { body { margin: 0; } .no-print { display: none !important; } }
`;

function buildOrderPrintableDocumentHtml(order, options = {}) {
  const includeActionBar = options.includeActionBar !== false;
  const safeClientTitle = String(order.nombre_cliente || "CLIENTE").toUpperCase().replace(/[^A-Z0-9ÁÉÍÓÚÑ ]/gi, "").trim();
  const waApprovalMsg = buildWhatsAppPdfApprovalMessage(order);
  const intlPhone = formatWhatsAppPhone(order.telefono_cliente);
  const waApprovalUrl = intlPhone ? `https://wa.me/${intlPhone}?text=${encodeURIComponent(waApprovalMsg)}` : "";
  const bodyHtml = buildOrderPrintableBodySection(order);

  const actionBlock = includeActionBar
    ? `
      <div class="no-print action-bar">
        <button type="button" class="action-btn" onclick="window.print()" style="background:#0f1638; color:#fff;">
          🖨️ Imprimir / Guardar PDF
        </button>
        <button type="button" class="action-btn" id="btn-drive-pdf" onclick="archiveThisPdfToDrive()" style="background:#0284c7; color:#fff;">
          ☁️ Archivar PDF en Google Drive
        </button>
        <button type="button" class="action-btn" id="btn-copy-wa-msg" onclick="copyApprovalMsg()" style="background:#eab308; color:#0f172a;">
          📋 Copiar Mensaje "Esperando Aprobación"
        </button>
        ${
          waApprovalUrl
            ? `<a href="${waApprovalUrl}" target="_blank" rel="noopener" class="action-btn" style="background:#16a34a; color:#fff;">
                 💬 Abrir WhatsApp ("Esperando Aprobación")
               </a>`
            : ""
        }
      </div>
      <script>
        var APPROVAL_MSG = ${JSON.stringify(waApprovalMsg)};
        var ORDER_ID_FOR_DRIVE = ${JSON.stringify(order.id_orden)};
        function copyApprovalMsg() {
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(APPROVAL_MSG).then(function() {
              var b = document.getElementById('btn-copy-wa-msg');
              if (b) { b.textContent = '✅ Mensaje Copiado (Listo para pegar con el PDF)'; }
            });
          } else {
            window.prompt('Copia el mensaje para enviar junto al PDF:', APPROVAL_MSG);
          }
        }
        function archiveThisPdfToDrive() {
          var b = document.getElementById('btn-drive-pdf');
          if (window.opener && typeof window.opener.archiveOrderPdfToDrive === 'function') {
            if (b) { b.textContent = '⏳ Guardando PDF en Google Drive...'; b.disabled = true; }
            window.opener.archiveOrderPdfToDrive(ORDER_ID_FOR_DRIVE).then(function(res) {
              if (b) {
                b.disabled = false;
                b.textContent = res && res.ok ? '✅ PDF Guardado en Drive' : '⚠️ Reintentar Drive';
              }
            });
          } else {
            alert('Usa el botón "Archivo PDF / Exportar por Fecha" desde la ventana principal de la app.');
          }
        }
        window.onload = function() {
          setTimeout(function() { window.print(); }, 450);
        };
      </script>
    `
    : "";

  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${escapeHtml(safeClientTitle)} Orden #${escapeHtml(order.codigo_troquel)}</title><style>${ORDER_PDF_SHARED_CSS}</style></head><body>${bodyHtml}${actionBlock}</body></html>`;
}

function printOrderExcelSheet(orderId) {
  if (currentUser && currentUser.rol === "tecnico") {
    showToast("Acceso restringido: Las hojas de presupuesto y facturación son exclusivas de Gerencia y Recepción.", "warning");
    return;
  }
  const order = db.ordenes.find((o) => o.id_orden === orderId);
  if (!order) {
    showToast("Orden no encontrada.", "error");
    return;
  }

  const printWindow = window.open("", "_blank");
  if (!printWindow) {
    showToast("Por favor permite las ventanas emergentes para imprimir la planilla.", "warning");
    return;
  }

  printWindow.document.write(buildOrderPrintableDocumentHtml(order, { includeActionBar: true }));
  printWindow.document.close();
}

async function archiveOrderPdfToDrive(orderId, silent = false) {
  const order = db.ordenes.find((o) => o.id_orden === orderId);
  if (!order) return { ok: false, error: "Orden no encontrada" };

  const orderDate = cleanDateISO(order.fecha_ingreso, false) || new Date().toISOString().slice(0, 10);
  const safeClient = String(order.nombre_cliente || "CLIENTE").toUpperCase().replace(/[^A-Z0-9]+/gi, "_").slice(0, 28);
  const fileName = `${orderDate}_Orden_${order.codigo_troquel}_${safeClient}.pdf`;
  const cleanHtml = buildOrderPrintableDocumentHtml(order, { includeActionBar: false });

  if (!silent) showToast(`Generando y archivando PDF de Orden #${order.codigo_troquel} en Google Drive...`, "info");
  try {
    const res = await fetch(GAS_API_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({
        action: "save_order_pdf",
        orderId: order.id_orden,
        troquel: order.codigo_troquel,
        orderDate,
        fileName,
        html: cleanHtml
      })
    });
    const json = await res.json();
    if (json && json.success && json.data && json.data.url) {
      if (!silent) {
        Swal.fire({
          icon: "success",
          title: `PDF Archivado en Google Drive`,
          html: `Orden <strong>#${escapeHtml(order.codigo_troquel)}</strong> guardada en carpeta <code>Rectificadora_Renacer_Facturas_PDF/${escapeHtml(json.data.monthFolder || "")}</code>.<br/><br/><a href="${json.data.url}" target="_blank" rel="noopener" style="color:#0284c7; font-weight:800;">📄 Abrir PDF en Google Drive</a>`,
          confirmButtonColor: "#182254"
        });
      }
      return { ok: true, data: json.data };
    }
    throw new Error((json && json.error) || "Actualiza Code.gs a v40 para habilitar el archivado de PDFs en Drive.");
  } catch (err) {
    if (!silent) {
      showToast(`No se pudo archivar el PDF en Drive: ${err.message || err}`, "error");
    }
    return { ok: false, error: String(err && err.message ? err.message : err) };
  }
}

function getFilteredOrdersForPdfExport(dateFrom, dateTo, statusFilter) {
  return (db.ordenes || []).filter((o) => {
    if (!o || o.estado_actual === "anulado") return false;
    const d = cleanDateISO(o.fecha_ingreso, false);
    if (dateFrom && d && d < dateFrom) return false;
    if (dateTo && d && d > dateTo) return false;
    if (statusFilter === "entregado" && o.estado_actual !== "entregado" && o.estado_actual !== "entrega" && o.estado_actual !== "archivado") return false;
    if (statusFilter === "pagadas" && Number(o.saldo_pendiente) > 0) return false;
    if (statusFilter === "pendientes" && Number(o.saldo_pendiente) <= 0) return false;
    return true;
  });
}

function updatePdfExportRangePreview() {
  const fromVal = document.getElementById("pdf-exp-from")?.value || "";
  const toVal = document.getElementById("pdf-exp-to")?.value || "";
  const statusVal = document.getElementById("pdf-exp-status")?.value || "all";
  const matched = getFilteredOrdersForPdfExport(fromVal, toVal, statusVal);
  const totalFacturado = matched.reduce((a, o) => a + (Number(o.monto_total) || 0), 0);
  const totalCobrado = matched.reduce((a, o) => a + (Number(o.monto_abonado) || 0), 0);
  const el = document.getElementById("pdf-exp-summary");
  if (el) {
    el.innerHTML = `<strong>${matched.length} orden(es)</strong> en el rango seleccionado · Total Presupuestado/Facturado: <strong style="color:var(--renacer-gold);">$${totalFacturado.toFixed(2)}</strong> · Cobrado: <strong style="color:#22c55e;">$${totalCobrado.toFixed(2)}</strong>`;
  }
}

function printBatchOrdersPdfByDate() {
  const fromVal = document.getElementById("pdf-exp-from")?.value || "";
  const toVal = document.getElementById("pdf-exp-to")?.value || "";
  const statusVal = document.getElementById("pdf-exp-status")?.value || "all";
  const matched = getFilteredOrdersForPdfExport(fromVal, toVal, statusVal);
  if (!matched.length) {
    showToast("No se encontraron órdenes en el rango de fechas seleccionado.", "warning");
    return;
  }

  const totalMonto = matched.reduce((a, o) => a + (Number(o.monto_total) || 0), 0);
  const totalAbono = matched.reduce((a, o) => a + (Number(o.monto_abonado) || 0), 0);
  const totalSaldo = matched.reduce((a, o) => a + (Number(o.saldo_pendiente) || 0), 0);
  const rangeLabel = `${fromVal ? formatDateHuman(fromVal, false) : "Inicio"} al ${toVal ? formatDateHuman(toVal, false) : "Hoy"}`;

  const summaryRows = matched
    .map(
      (o, idx) => `
      <tr>
        <td style="border:1px solid #cbd5e1; padding:5px 8px; text-align:center;">${idx + 1}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px; font-weight:800;">#${escapeHtml(o.codigo_troquel)}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px;">${formatDateHuman(o.fecha_ingreso, false)}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px;">${escapeHtml(o.nombre_cliente)}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px;">${escapeHtml(o.datos_motor?.marca || "")} ${escapeHtml(o.datos_motor?.modelo || "")}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px; text-align:right; font-weight:800;">$${Number(o.monto_total).toFixed(2)}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px; text-align:right; color:#16a34a;">$${Number(o.monto_abonado).toFixed(2)}</td>
        <td style="border:1px solid #cbd5e1; padding:5px 8px; text-align:right; color:${o.saldo_pendiente > 0 ? "#dc2626" : "#16a34a"};">$${Number(o.saldo_pendiente).toFixed(2)}</td>
      </tr>
    `
    )
    .join("");

  const sheetsHtml = matched
    .map((o, idx) => `<div class="${idx < matched.length - 1 ? "page-break" : ""}">${buildOrderPrintableBodySection(o)}</div>`)
    .join("");

  const win = window.open("", "_blank");
  if (!win) {
    showToast("Permite ventanas emergentes para generar el dossier PDF.", "warning");
    return;
  }

  win.document.write(`
    <!DOCTYPE html>
    <html lang="es">
    <head>
      <meta charset="UTF-8">
      <title>Expediente de Órdenes y Facturas (${rangeLabel}) — Rectificadora Renacer</title>
      <style>${ORDER_PDF_SHARED_CSS}</style>
    </head>
    <body>
      <div class="page-break">
        <div class="header-box">
          <div>
            <div class="title-company">RECTIFICADORA RENACER C.A.</div>
            <div class="biblical-quote">EXPEDIENTE CONSOLIDADO DE ÓRDENES / FACTURAS POR FECHA</div>
            <div style="font-size:12px; color:#475569; margin-top:4px;">Período: <strong>${escapeHtml(rangeLabel)}</strong> · Total documentos: <strong>${matched.length}</strong></div>
          </div>
          <div class="order-badge-box">
            <div style="font-size:11px; color:#64748b; font-weight:bold;">TOTAL FACTURADO</div>
            <div style="font-size:22px; font-weight:900; color:#0f1638;">$${totalMonto.toFixed(2)}</div>
            <div style="font-size:11px; color:#16a34a; font-weight:bold;">Cobrado: $${totalAbono.toFixed(2)} · Resto: $${totalSaldo.toFixed(2)}</div>
          </div>
        </div>
        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Orden</th>
              <th>Fecha</th>
              <th style="text-align:left;">Cliente</th>
              <th style="text-align:left;">Motor / Pieza</th>
              <th style="text-align:right;">Total ($)</th>
              <th style="text-align:right;">Abonado ($)</th>
              <th style="text-align:right;">Saldo ($)</th>
            </tr>
          </thead>
          <tbody>${summaryRows}</tbody>
        </table>
      </div>
      ${sheetsHtml}
      <div class="no-print action-bar">
        <button type="button" class="action-btn" onclick="window.print()" style="background:#0f1638; color:#fff;">🖨️ Imprimir / Guardar Expediente Completo en PDF</button>
      </div>
      <script>window.onload = function() { setTimeout(function() { window.print(); }, 500); };</script>
    </body>
    </html>
  `);
  win.document.close();
}

async function archiveBatchOrdersToDrive() {
  const fromVal = document.getElementById("pdf-exp-from")?.value || "";
  const toVal = document.getElementById("pdf-exp-to")?.value || "";
  const statusVal = document.getElementById("pdf-exp-status")?.value || "all";
  const matched = getFilteredOrdersForPdfExport(fromVal, toVal, statusVal);
  if (!matched.length) {
    showToast("No hay órdenes en ese rango de fechas para archivar.", "warning");
    return;
  }

  const progEl = document.getElementById("pdf-drive-batch-progress");
  let savedCount = 0;
  let lastError = "";
  for (let i = 0; i < matched.length; i++) {
    const o = matched[i];
    if (progEl) {
      progEl.innerHTML = `<i class="fas fa-spinner fa-spin" style="color:var(--renacer-gold);"></i> Archivando en Google Drive (${i + 1} de ${matched.length}): Orden #${escapeHtml(o.codigo_troquel)}...`;
    }
    const r = await archiveOrderPdfToDrive(o.id_orden, true);
    if (r.ok) savedCount++;
    else lastError = r.error || "Error de conexión";
  }

  if (progEl) {
    progEl.innerHTML = savedCount > 0
      ? `<span style="color:#22c55e; font-weight:800;"><i class="fas fa-check-circle"></i> ${savedCount} de ${matched.length} PDF(s) guardados en Google Drive.</span>`
      : `<span style="color:#ef4444; font-weight:800;"><i class="fas fa-exclamation-triangle"></i> ${escapeHtml(lastError)}</span>`;
  }
  loadDriveArchivedPdfsList();
}

async function loadDriveArchivedPdfsList() {
  const box = document.getElementById("pdf-drive-list-box");
  if (!box) return;
  const fromVal = document.getElementById("pdf-exp-from")?.value || "";
  const toVal = document.getElementById("pdf-exp-to")?.value || "";
  box.innerHTML = `<div style="text-align:center; padding:16px; color:var(--text-muted); font-size:12px;"><i class="fas fa-spinner fa-spin" style="color:var(--renacer-gold);"></i> Consultando carpeta <code>Rectificadora_Renacer_Facturas_PDF</code> en Google Drive...</div>`;

  try {
    const qs = `action=list_order_pdfs&dateFrom=${encodeURIComponent(fromVal)}&dateTo=${encodeURIComponent(toVal)}&t=${Date.now()}`;
    const res = await fetch(`${GAS_API_URL}?${qs}`);
    const json = await res.json();
    if (!json || !json.success || !json.data || !Array.isArray(json.data.files)) {
      box.innerHTML = `<div style="background:rgba(245,158,11,0.12); border:1px solid rgba(245,158,11,0.4); border-radius:10px; padding:12px; font-size:12px;">Actualiza <code>Code.gs</code> a la versión <strong>v40</strong> en Google Apps Script para consultar y archivar PDFs directamente en Google Drive. Mientras tanto puedes usar <strong>"Imprimir / Guardar Expediente en PDF"</strong> arriba.</div>`;
      return;
    }

    const files = json.data.files;
    const folderBtn = json.data.rootFolderUrl
      ? `<a href="${json.data.rootFolderUrl}" target="_blank" rel="noopener" class="btn btn--gold btn--xs" style="text-decoration:none;"><i class="fab fa-google-drive"></i> Abrir Carpeta Completa en Drive</a>`
      : "";

    if (!files.length) {
      box.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
          <span style="font-size:12px; color:var(--text-muted);">No hay PDFs archivados en Google Drive para ese rango todavía.</span>
          ${folderBtn}
        </div>
      `;
      return;
    }

    box.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:8px;">
        <span style="font-size:12px; font-weight:900; color:#38bdf8;"><i class="fab fa-google-drive"></i> ${files.length} PDF(s) archivados en Google Drive</span>
        ${folderBtn}
      </div>
      <div style="max-height:220px; overflow-y:auto;">
        ${files
          .map(
            (f) => `
          <div class="backup-item-row">
            <div>
              <div style="font-weight:800; font-size:12px;"><i class="fas fa-file-pdf" style="color:#ef4444; margin-right:5px;"></i>${escapeHtml(f.name)}</div>
              <div style="font-size:11px; color:var(--text-muted);">Carpeta: ${escapeHtml(f.monthFolder)} · Fecha: ${escapeHtml(f.orderDate)}</div>
            </div>
            <div style="display:flex; gap:6px;">
              <a href="${f.url}" target="_blank" rel="noopener" class="btn btn--ghost btn--xs" style="text-decoration:none;"><i class="fas fa-eye"></i> Ver</a>
              <a href="${f.downloadUrl}" target="_blank" rel="noopener" class="btn btn--gold btn--xs" style="text-decoration:none;"><i class="fas fa-download"></i> Descargar</a>
            </div>
          </div>
        `
          )
          .join("")}
      </div>
    `;
  } catch (err) {
    box.innerHTML = `<div style="color:#f87171; font-size:12px;">No se pudo consultar Google Drive en este momento. Puedes generar el expediente PDF local arriba.</div>`;
  }
}

function openPdfArchiveAndExportModal() {
  const today = new Date().toISOString().slice(0, 10);
  const firstOfMonth = today.slice(0, 8) + "01";
  const defFrom = dateFilterFrom || firstOfMonth;
  const defTo = dateFilterTo || today;

  openModal({
    title: "Archivo de Facturas / Órdenes PDF (Drive y Exportación por Fecha)",
    icon: "fa-file-pdf",
    wide: true,
    body: `
      <div class="form-section-box" style="border-color:rgba(245,223,0,0.45);">
        <div class="form-section-title"><i class="fas fa-calendar-days"></i> 1. Filtrar y Extraer Órdenes / Facturas por Rango de Fechas</div>
        <div class="form-grid-3" style="margin-bottom:10px;">
          <div class="form-field">
            <label>Desde *</label>
            <input type="date" id="pdf-exp-from" value="${defFrom}" onchange="updatePdfExportRangePreview(); loadDriveArchivedPdfsList();" />
          </div>
          <div class="form-field">
            <label>Hasta *</label>
            <input type="date" id="pdf-exp-to" value="${defTo}" onchange="updatePdfExportRangePreview(); loadDriveArchivedPdfsList();" />
          </div>
          <div class="form-field">
            <label>Estado de Órdenes</label>
            <select id="pdf-exp-status" onchange="updatePdfExportRangePreview()">
              <option value="all">Todas (Excepto Anuladas)</option>
              <option value="entregado">Solo Entregadas / Archivadas</option>
              <option value="pagadas">Solo 100% Pagadas</option>
              <option value="pendientes">Solo con Saldo Pendiente</option>
            </select>
          </div>
        </div>
        <div id="pdf-exp-summary" style="font-size:12.5px; color:var(--text-main); margin-bottom:12px;"></div>
        <div style="display:flex; gap:8px; flex-wrap:wrap;">
          <button type="button" class="btn btn--gold" onclick="printBatchOrdersPdfByDate()">
            <i class="fas fa-print"></i> Generar Expediente Consolidado en PDF (Imprimir / Descargar)
          </button>
          <button type="button" class="btn btn--primary" onclick="archiveBatchOrdersToDrive()">
            <i class="fab fa-google-drive"></i> Archivar Lote Individual en Carpeta Google Drive
          </button>
        </div>
        <div id="pdf-drive-batch-progress" style="font-size:12px; margin-top:8px;"></div>
      </div>

      <div class="form-section-box" style="margin-bottom:0; border-color:rgba(56,189,248,0.4);">
        <div class="form-section-title" style="display:flex; justify-content:space-between; align-items:center;">
          <span><i class="fab fa-google-drive" style="color:#38bdf8;"></i> 2. PDFs Ya Archivados en Google Drive (Por Carpeta Mensual)</span>
          <button type="button" class="btn btn--ghost btn--xs" onclick="loadDriveArchivedPdfsList()">
            <i class="fas fa-rotate"></i> Actualizar Lista
          </button>
        </div>
        <div id="pdf-drive-list-box"></div>
      </div>
    `,
    footer: `
      <button type="button" class="btn btn--ghost" onclick="closeModal()">Cerrar</button>
    `
  });

  updatePdfExportRangePreview();
  loadDriveArchivedPdfsList();
}
/* ============================================================================
   INSTALACIÓN PWA Y ARRANQUE AUTOMÁTICO CON RELOJ EN TIEMPO REAL
   ============================================================================ */
window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  deferredInstallPrompt = e;
  const btn = document.getElementById("pwa-install-btn");
  if (btn) btn.classList.remove("hidden");
});

function triggerPwaInstall() {
  if (!deferredInstallPrompt) return;
  deferredInstallPrompt.prompt();
}

window.addEventListener("DOMContentLoaded", () => {
  initTheme();
  db = loadDatabase();
  populateLoginSelect();

  // Verificación proactiva de versión y limpieza de caché
  checkAppVersionAndCache();

  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("./sw.js").catch(() => {});
  }

  // Cronómetro en tiempo real (Fase 3): actualiza cada segundo los trabajos "En Proceso"
  setInterval(tickLiveSubtaskTimers, 1000);

  // Sincronización automática de fondo cada 20 segundos (zero-cost con sinceRev <1s cuando no hay cambios)
  setInterval(() => syncFromGoogleSheets(true), 20000);

  // Sincronizar automáticamente en vivo al regresar a la pestaña; al salir, empujar cualquier cambio pendiente con keepalive
  window.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      if (hasUnsyncedLocalChanges || cloudPushPending || cloudPushDebounceTimer) {
        sendKeepaliveCloudPushOnExit();
      }
    } else if (!lastCloudPullDoneTs || Date.now() - lastCloudPullDoneTs >= 6000) {
      syncFromGoogleSheets(true);
    }
  });
  window.addEventListener("pagehide", () => {
    if (hasUnsyncedLocalChanges || cloudPushPending || cloudPushDebounceTimer) {
      sendKeepaliveCloudPushOnExit();
    }
  });
  window.addEventListener("online", () => {
    if (hasUnsyncedLocalChanges) {
      cloudPushConsecutiveFailures = 0;
      showToast("Conexión restablecida. Respaldando cambios pendientes en Google Sheets...", "info");
      flushCloudPush(false);
    } else {
      syncFromGoogleSheets(true);
    }
  });
  window.addEventListener("focus", () => {
    if (!lastCloudPullDoneTs || Date.now() - lastCloudPullDoneTs >= 6000) {
      syncFromGoogleSheets(true);
    }
  });
  // Sincronización en tiempo real entre pestañas abiertas del mismo navegador (evita peleas entre perfiles en la misma PC)
  window.addEventListener("storage", (ev) => {
    try {
      if (ev.key === CLOUD_REV_KEY && ev.newValue) {
        const nextRev = Number(ev.newValue) || 0;
        if (nextRev > lastKnownCloudRevision) lastKnownCloudRevision = nextRev;
      }
      if (ev.key === SYNC_BASE_DIGESTS_KEY && ev.newValue) {
        const parsedBase = safeJsonParse(ev.newValue, null);
        if (parsedBase && typeof parsedBase === "object") lastSyncedRecordDigests = parsedBase;
      }
      if (ev.key === STORAGE_KEY && ev.newValue && !hasUnsyncedLocalChanges && !cloudPushInFlight && !isAnyModalOpen()) {
        const parsedDb = safeJsonParse(ev.newValue, null);
        if (parsedDb && Array.isArray(parsedDb.usuarios)) {
          db = normalizeDatabaseSchema(parsedDb);
          if (currentUser) renderApp();
        }
      }
    } catch (e) {}
  });
  window.addEventListener("beforeunload", (e) => {
    if (hasUnsyncedLocalChanges || cloudPushInFlight || cloudPushPending || cloudPushDebounceTimer) {
      sendKeepaliveCloudPushOnExit();
      e.preventDefault();
      e.returnValue = "";
    }
  });

  // Secuencia segura de arranque:
  // - Si había cambios locales sin subir de una sesión anterior, subirlos/fusionarlos PRIMERO para jamás perder trabajo.
  // - Si todo estaba al día, leer primero Google Sheets y DESPUÉS consultar tasas BCV/Paralelo.
  const startInitialSync = async () => {
    if (hasUnsyncedLocalChanges) {
      updateCloudSyncBadge("pending");
      scheduleCloudRetry();
      await flushCloudPush(true, { reason: "Recuperación automática de cambios locales pendientes" });
    }
    await syncFromGoogleSheets(true);
    fetchLiveExchangeRates(true);
    setInterval(() => fetchLiveExchangeRates(true), 30 * 60 * 1000);
  };

  // RESTAURACIÓN AUTOMÁTICA DE SESIÓN (Persistencia en refresco / F5; nunca restaurar perfiles externos)
  const savedUserId = localStorage.getItem(SESSION_KEY);
  if (savedUserId) {
    const user = (db.usuarios || []).find((u) => u.id_usuario === savedUserId);
    if (user && user.activo !== false && !isExternalUser(user)) {
      currentUser = user;
      if (isJavierRestrictedUser(user)) currentTab = "inventario";
      else if (user.rol === "tecnico") currentTab = "worker_panel";
      document.getElementById("login-view")?.classList.add("hidden");
      document.getElementById("workspace")?.classList.remove("hidden");
      renderApp();
      startInitialSync();
      return;
    } else if (user && isExternalUser(user)) {
      localStorage.removeItem(SESSION_KEY);
    }
  }

  // Si no hay sesión activa previa, mostrar pantalla de acceso limpia
  document.getElementById("workspace")?.classList.add("hidden");
  document.getElementById("login-view")?.classList.remove("hidden");
  startInitialSync();
});
